import type { User } from 'firebase/auth'
import { onAuthStateChanged, signInWithPopup, signInWithRedirect, getRedirectResult, signOut } from 'firebase/auth'

export interface SerializedUser {
  uid: string
  email: string | null
  displayName: string | null
  photoURL: string | null
}

function serializeUser(fbUser: User | null): SerializedUser | null {
  if (!fbUser) return null
  return {
    uid: fbUser.uid,
    email: fbUser.email,
    displayName: fbUser.displayName,
    photoURL: fbUser.photoURL
  }
}

let initPromise: Promise<SerializedUser | null> | null = null
let unsubscribe: (() => void) | null = null

export const useFirebaseAuth = () => {
  const nuxtApp = useNuxtApp()

  const config = useRuntimeConfig()

  const user = useState<SerializedUser | null>('firebase:user', () => null)
  const loading = useState<boolean>('firebase:loading', () => true)

  const adminEmails = computed(() => {
    const raw = (config.public.adminEmails || '').trim()
    if (!raw) return [] as string[]

    return raw
      .split(',')
      .map((email) => email.trim().toLowerCase())
      .filter(Boolean)
  })

  const isAdmin = computed(() => {
    const email = user.value?.email?.toLowerCase()
    if (!email) return false
    return adminEmails.value.includes(email)
  })

  const init = () => {
    // Skip on server - Firebase Auth only works on client
    if (import.meta.server) {
      loading.value = false
      return Promise.resolve(null)
    }

    if (initPromise) return initPromise

    initPromise = new Promise(async (resolve) => {
      const auth = nuxtApp.$firebaseAuth as any

      if (!auth) {
        loading.value = false
        resolve(null)
        return
      }

      if (unsubscribe) {
        resolve(user.value)
        return
      }

      // Handle redirect result if returning from Google sign-in
      try {
        await getRedirectResult(auth)
      } catch (error) {
        // Ignore redirect errors - they're common and not critical
      }

      unsubscribe = onAuthStateChanged(auth, (nextUser: User | null) => {
        user.value = serializeUser(nextUser)
        loading.value = false
        resolve(user.value)
      })
    })

    return initPromise
  }

  const signInWithGoogle = async () => {
    if (import.meta.server) return
    const auth = nuxtApp.$firebaseAuth as any
    const provider = nuxtApp.$firebaseGoogleProvider as any
    if (!auth || !provider) return

    try {
      // Try popup first (more reliable for development)
      await signInWithPopup(auth, provider)
    } catch (error: any) {
      // If popup is blocked or fails, fall back to redirect
      if (error?.code === 'auth/popup-blocked' || error?.code === 'auth/popup-closed-by-user') {
        await signInWithRedirect(auth, provider)
      } else {
        console.error('Sign in error:', error)
        throw error
      }
    }
  }

  const signOutUser = async () => {
    if (import.meta.server) return
    const auth = nuxtApp.$firebaseAuth as any
    if (!auth) return
    await signOut(auth)
  }

  return {
    user,
    loading,
    isAdmin,
    init,
    signInWithGoogle,
    signOut: signOutUser
  }
}

